tool_input.command:
node -e '
const fs=require("fs"),vm=require("vm");
const html=fs.readFileSync("game.html","utf8");
const m=html.match(/<script>([\s\S]*?)<\/script>/);
if(!m){console.log("NO SCRIPT");process.exit(1);}
const ctx={console};ctx.globalThis=ctx;
vm.createContext(ctx);
try{ vm.runInContext(m[1],ctx,{filename:"game.js"}); }
catch(e){ console.log("SCRIPT ERROR: "+e.stack); process.exit(1); }
const A=ctx.__ASHFALL__;
console.log("loaded ok, exports:",Object.keys(A).join(","));
const r=A.runTests();
console.log(r.lines.join("\n"));
'

